// What a machine holds, read and written by path, as a C expression names it
// on the machine's struct: cpu.pc, crtc.registers[12], fdc.identities[3][1].
// Each structure's impl is generated by build.rs from bindgen's rendering of
// the headers, so a field keeps the name its header gives it.

use serde_json::{Map, Value};

#[allow(clippy::wildcard_imports)]
use crate::emulator::*;

#[derive(Debug, PartialEq)]
pub enum Segment {
    Field(String),
    Index(usize),
}

pub trait Fields {
    fn encode(&self) -> Value;
    fn get(&self, path: &[Segment]) -> Result<Value, String>;
    fn set(&mut self, path: &[Segment], value: &Value) -> Result<(), String>;
}

const PATH_FORM: &str = "a path names fields with dots and indexes arrays in decimal in brackets, \
                         as cpu.pc or crtc.registers[12] do";

pub fn parse(path: &str) -> Result<Vec<Segment>, String> {
    let mut segments = Vec::new();
    if path.is_empty() {
        return Ok(segments);
    }
    for part in path.split('.') {
        let (name, mut rest) = part.split_at(part.find('[').unwrap_or(part.len()));
        let is_name = name.starts_with(|first: char| first.is_ascii_alphabetic() || first == '_')
            && name
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || character == '_');
        if !is_name {
            return Err(format!("{path} is not a path: {PATH_FORM}"));
        }
        segments.push(Segment::Field(name.to_owned()));
        while !rest.is_empty() {
            // Decimal, as C reads an index with no leading 0.
            let index = rest
                .strip_prefix('[')
                .and_then(|inside| inside.split_once(']'))
                .filter(|(index, _)| index.bytes().all(|digit| digit.is_ascii_digit()))
                .filter(|(index, _)| *index == "0" || !index.starts_with('0'))
                .and_then(|(index, after)| Some((index.parse().ok()?, after)));
            let Some((index, after)) = index else {
                return Err(format!("{path} is not a path: {PATH_FORM}"));
            };
            segments.push(Segment::Index(index));
            rest = after;
        }
    }
    Ok(segments)
}

fn describe(segment: &Segment) -> String {
    match segment {
        Segment::Field(name) => name.clone(),
        Segment::Index(index) => format!("[{index}]"),
    }
}

fn no_field(structure: &str, name: &str, fields: &[&str]) -> String {
    format!(
        "{structure} has no field {name}; its fields are {}",
        fields.join(", ")
    )
}

fn not_an_array(structure: &str, index: usize, fields: &[&str]) -> String {
    format!(
        "{structure} is a structure, reached by the name of a field and not by [{index}]; its \
         fields are {}",
        fields.join(", ")
    )
}

fn pointer() -> String {
    "a pointer, which is not followed; peek and poke reach memory as the processor does".to_owned()
}

fn inside_a_value(path: &[Segment]) -> String {
    format!(
        "a single value is read and written whole, and has nothing in it named {}",
        describe(&path[0])
    )
}

fn set_fields<T: Fields>(structure: &mut T, name: &str, value: &Value) -> Result<(), String> {
    let Value::Object(fields) = value else {
        return Err(format!(
            "{name} is a structure, set from an object of some of its fields, not from {value}"
        ));
    };
    for (field, value) in fields {
        structure
            .set(&[Segment::Field(field.clone())], value)
            .map_err(|problem| format!("{field}: {problem}"))?;
    }
    Ok(())
}

// Hexadecimal of up to so many digits, after the &, #, $ or 0x that marks it.
pub fn hexadecimal_number(value: &Value, most_digits: usize) -> Option<u64> {
    let digits = value.as_str().and_then(|text| {
        ["&", "#", "$", "0x", "0X"]
            .iter()
            .find_map(|prefix| text.strip_prefix(prefix))
    });
    digits
        .filter(|digits| {
            (1..=most_digits).contains(&digits.len())
                && digits.chars().all(|digit| digit.is_ascii_hexdigit())
        })
        .and_then(|digits| u64::from_str_radix(digits, 16).ok())
}

macro_rules! unsigned {
    ($($type:ty),*) => {$(
        impl Fields for $type {
            fn encode(&self) -> Value {
                Value::from(*self)
            }

            fn get(&self, path: &[Segment]) -> Result<Value, String> {
                if path.is_empty() { Ok(self.encode()) } else { Err(inside_a_value(path)) }
            }

            fn set(&mut self, path: &[Segment], value: &Value) -> Result<(), String> {
                if !path.is_empty() {
                    return Err(inside_a_value(path));
                }
                let digits = 2 * size_of::<$type>();
                *self = value
                    .as_u64()
                    .or_else(|| hexadecimal_number(value, digits))
                    .and_then(|number| <$type>::try_from(number).ok())
                    .ok_or_else(|| {
                        format!(
                            "expects an integer from 0 to {}, or hexadecimal from &{:0digits$X} \
                             to &{:X}, written with &, #, $ or 0x before it, not {value}",
                            <$type>::MAX,
                            0,
                            <$type>::MAX
                        )
                    })?;
                Ok(())
            }
        }
    )*};
}

macro_rules! signed {
    ($($type:ty),*) => {$(
        impl Fields for $type {
            fn encode(&self) -> Value {
                Value::from(*self)
            }

            fn get(&self, path: &[Segment]) -> Result<Value, String> {
                if path.is_empty() { Ok(self.encode()) } else { Err(inside_a_value(path)) }
            }

            fn set(&mut self, path: &[Segment], value: &Value) -> Result<(), String> {
                if !path.is_empty() {
                    return Err(inside_a_value(path));
                }
                *self = value
                    .as_i64()
                    .and_then(|number| <$type>::try_from(number).ok())
                    .ok_or_else(|| {
                        format!(
                            "expects an integer from {} to {}, not {value}",
                            <$type>::MIN,
                            <$type>::MAX
                        )
                    })?;
                Ok(())
            }
        }
    )*};
}

unsigned!(u8, u16, u32, u64);
signed!(i8, i32);

impl Fields for bool {
    fn encode(&self) -> Value {
        Value::from(*self)
    }

    fn get(&self, path: &[Segment]) -> Result<Value, String> {
        if path.is_empty() {
            Ok(self.encode())
        } else {
            Err(inside_a_value(path))
        }
    }

    fn set(&mut self, path: &[Segment], value: &Value) -> Result<(), String> {
        if !path.is_empty() {
            return Err(inside_a_value(path));
        }
        *self = value
            .as_bool()
            .ok_or_else(|| format!("expects true or false, not {value}"))?;
        Ok(())
    }
}

impl<T: Fields, const LENGTH: usize> Fields for [T; LENGTH] {
    fn encode(&self) -> Value {
        Value::Array(self.iter().map(Fields::encode).collect())
    }

    fn get(&self, path: &[Segment]) -> Result<Value, String> {
        match path.split_first() {
            None => Ok(self.encode()),
            Some((Segment::Index(index), rest)) => self
                .as_slice()
                .get(*index)
                .ok_or_else(|| past_the_end(*index, LENGTH))?
                .get(rest),
            Some((Segment::Field(name), _)) => Err(not_a_structure(LENGTH, name)),
        }
    }

    fn set(&mut self, path: &[Segment], value: &Value) -> Result<(), String> {
        match path.split_first() {
            None => {
                let Some(values) = value.as_array().filter(|values| values.len() == LENGTH) else {
                    return Err(format!(
                        "an array of {LENGTH} is set from an array of {LENGTH} values, not from \
                         {value}"
                    ));
                };
                for (index, (element, value)) in self.iter_mut().zip(values).enumerate() {
                    element
                        .set(&[], value)
                        .map_err(|problem| format!("[{index}]: {problem}"))?;
                }
                Ok(())
            }
            Some((Segment::Index(index), rest)) => self
                .as_mut_slice()
                .get_mut(*index)
                .ok_or_else(|| past_the_end(*index, LENGTH))?
                .set(rest, value),
            Some((Segment::Field(name), _)) => Err(not_a_structure(LENGTH, name)),
        }
    }
}

fn past_the_end(index: usize, length: usize) -> String {
    format!(
        "[{index}] is past the end of an array of {length}, whose elements are [0] to [{}]",
        length - 1
    )
}

fn not_a_structure(length: usize, name: &str) -> String {
    format!(
        "an array of {length} is reached by an index, [0] to [{}], and not by the name {name}",
        length - 1
    )
}

// A C enum's value goes by the name its header gives it.
fn enumerator<T: Copy + PartialEq + Into<Value>>(value: T, enumerators: &[(&str, T)]) -> Value {
    enumerators
        .iter()
        .find(|(_, enumerated)| *enumerated == value)
        .map_or_else(|| value.into(), |(name, _)| Value::from(*name))
}

fn get_enumerator<T: Copy + PartialEq + Into<Value>>(
    value: T,
    enumerators: &[(&str, T)],
    path: &[Segment],
) -> Result<Value, String> {
    if path.is_empty() {
        Ok(enumerator(value, enumerators))
    } else {
        Err(inside_a_value(path))
    }
}

fn set_enumerator<T: Copy>(
    field: &mut T,
    enumerators: &[(&str, T)],
    path: &[Segment],
    value: &Value,
) -> Result<(), String> {
    if !path.is_empty() {
        return Err(inside_a_value(path));
    }
    let names: Vec<&str> = enumerators.iter().map(|(name, _)| *name).collect();
    *field = enumerators
        .iter()
        .find(|(name, _)| value.as_str() == Some(name))
        .map(|(_, enumerated)| *enumerated)
        .ok_or_else(|| format!("expects one of {}, not {value}", names.join(", ")))?;
    Ok(())
}

// Every single value an encoding holds, by its path, as C names it.
#[cfg(test)]
pub(crate) fn leaves(value: &Value, path: &str, into: &mut Vec<(String, Value)>) {
    match value {
        Value::Object(fields) => {
            for (name, value) in fields {
                let path = if path.is_empty() {
                    name.clone()
                } else {
                    format!("{path}.{name}")
                };
                leaves(value, &path, into);
            }
        }
        Value::Array(values) => {
            for (index, value) in values.iter().enumerate() {
                leaves(value, &format!("{path}[{index}]"), into);
            }
        }
        _ => into.push((path.to_owned(), value.clone())),
    }
}

include!(concat!(env!("OUT_DIR"), "/fields.rs"));

#[cfg(test)]
mod tests {
    use super::*;
    use crate::machine::{Cpc, Spectrum};

    fn cpc() -> Cpc {
        Cpc::new(vec![0; 0x10000].into_boxed_slice(), Box::new([0; 0x4000]))
    }

    fn spectrum() -> Spectrum {
        Spectrum::new(
            vec![0; SPECTRUM_RAM_48K as usize].into_boxed_slice(),
            Box::new([0; SPECTRUM_ROM_SIZE as usize]),
        )
    }

    fn replaced(encoded: &Value, path: &[Segment], value: &Value) -> Value {
        let mut encoded = encoded.clone();
        let mut at = &mut encoded;
        for segment in path {
            at = match segment {
                Segment::Field(name) => &mut at[name.as_str()],
                Segment::Index(index) => &mut at[*index],
            };
        }
        *at = value.clone();
        encoded
    }

    // Each value is written to a copy of the machine, changed so that it
    // differs, an enum's to another of its enumerators, and must read back as
    // written while every other value reads as it did: each path reaches a
    // field of its own, and the same one both ways.
    fn every_value_reads_back_alone<T: Fields>(machine: &T) {
        let encoded = machine.encode();
        let mut values = Vec::new();
        leaves(&encoded, "", &mut values);
        assert!(values.len() > 50, "{} values", values.len());
        for (path, value) in values {
            let segments = parse(&path).unwrap();
            // SAFETY: a machine's struct owns nothing, and the copy is only
            // written and read.
            let mut copy = unsafe { std::ptr::read(machine) };
            let flipped = match &value {
                Value::Bool(truth) => Value::from(!truth),
                Value::Number(number) => Value::from(number.as_u64().expect("a count") ^ 1),
                _ => ENUMERATORS
                    .iter()
                    .map(|name| Value::from(*name))
                    .find(|name| *name != value && copy.set(&segments, name).is_ok())
                    .expect("an enum of more than one enumerator"),
            };
            copy.set(&segments, &flipped).unwrap();
            assert_eq!(copy.get(&segments).unwrap(), flipped, "{path}");
            assert_eq!(
                copy.encode(),
                replaced(&encoded, &segments, &flipped),
                "{path}"
            );
        }
    }

    #[test]
    fn every_value_of_a_cpc_reads_back_alone() {
        every_value_reads_back_alone(cpc().machine());
    }

    #[test]
    fn every_value_of_a_spectrum_reads_back_alone() {
        every_value_reads_back_alone(spectrum().machine());
    }

    // What the headers hold by pointer, and nothing else, is left out:
    // cpc.h, spectrum.h, monitor.h, upd765.h and drive.h.
    #[test]
    fn only_pointers_are_left_out() {
        assert_eq!(
            POINTERS,
            [
                "cpc_t.lower_rom",
                "cpc_t.ram",
                "cpc_t.read_page",
                "cpc_t.tape",
                "cpc_t.upper_roms",
                "cpc_t.write_page",
                "drive_t.floppy",
                "monitor_t.framebuffer",
                "spectrum_t.ram",
                "spectrum_t.rom",
                "spectrum_t.tape",
                "upd765_t.drive",
                "upd765_t.drives",
            ]
        );
    }

    #[test]
    fn an_enum_goes_by_its_enumerators_names() {
        let cpc = cpc();
        let path = parse("fdc.phase").unwrap();
        assert_eq!(cpc.machine().get(&path).unwrap(), "UPD765_PHASE_IDLE");
        // SAFETY: as above.
        let mut copy = unsafe { std::ptr::read(cpc.machine()) };
        copy.set(&path, &Value::from("UPD765_PHASE_RESULT"))
            .unwrap();
        assert_eq!(copy.fdc.phase, upd765_phase_UPD765_PHASE_RESULT);
        assert_eq!(
            copy.set(&path, &Value::from(3)).unwrap_err(),
            "expects one of UPD765_PHASE_IDLE, UPD765_PHASE_COMMAND, UPD765_PHASE_EXECUTION, \
             UPD765_PHASE_RESULT, not 3"
        );
    }

    #[test]
    fn a_path_that_reaches_nothing_says_what_would() {
        let cpc = cpc();
        let refusal = |path: &str| cpc.machine().get(&parse(path).unwrap()).unwrap_err();
        assert!(
            refusal("crtc.nope").starts_with(
                "crtc_t has no field nope; its fields are registers, address_register,"
            ),
            "{}",
            refusal("crtc.nope")
        );
        assert!(
            refusal("crtc[0]").starts_with(
                "crtc_t is a structure, reached by the name of a field and not by [0]; its fields \
                 are registers, address_register,"
            ),
            "{}",
            refusal("crtc[0]")
        );
        assert_eq!(
            refusal("crtc.registers.r12"),
            "an array of 18 is reached by an index, [0] to [17], and not by the name r12"
        );
        assert_eq!(
            refusal("crtc.registers[18]"),
            "[18] is past the end of an array of 18, whose elements are [0] to [17]"
        );
        assert_eq!(
            refusal("cpu.pc.low"),
            "a single value is read and written whole, and has nothing in it named low"
        );
        assert_eq!(
            refusal("ram"),
            "a pointer, which is not followed; peek and poke reach memory as the processor does"
        );
    }

    #[test]
    fn a_value_of_the_wrong_kind_says_what_would_do() {
        let cpc = cpc();
        // SAFETY: as above.
        let mut copy = unsafe { std::ptr::read(cpc.machine()) };
        let mut refusal =
            |path: &str, value: Value| copy.set(&parse(path).unwrap(), &value).unwrap_err();
        assert_eq!(
            refusal("cpu.pc", Value::from(65536)),
            "expects an integer from 0 to 65535, or hexadecimal from &0000 to &FFFF, written \
             with &, #, $ or 0x before it, not 65536"
        );
        assert_eq!(
            refusal("cpu.a", Value::from(-1)),
            "expects an integer from 0 to 255, or hexadecimal from &00 to &FF, written with &, \
             #, $ or 0x before it, not -1"
        );
        // A field takes no more digits than it has, as an address takes four.
        assert_eq!(
            refusal("cpu.a", Value::from("&005")),
            "expects an integer from 0 to 255, or hexadecimal from &00 to &FF, written with &, \
             #, $ or 0x before it, not \"&005\""
        );
        assert_eq!(
            refusal("cpu.a", Value::from("&100")),
            "expects an integer from 0 to 255, or hexadecimal from &00 to &FF, written with &, \
             #, $ or 0x before it, not \"&100\""
        );
        assert_eq!(
            refusal("fdc.sector", Value::from(1u64 << 31)),
            "expects an integer from -2147483648 to 2147483647, not 2147483648"
        );
        assert_eq!(
            refusal("cpu.iff1", Value::from(1)),
            "expects true or false, not 1"
        );
        assert_eq!(
            refusal("crtc.registers", Value::from(vec![1, 2])),
            "an array of 18 is set from an array of 18 values, not from [1,2]"
        );
        assert_eq!(
            refusal("cpu", Value::from(5)),
            "z80_t is a structure, set from an object of some of its fields, not from 5"
        );
        assert_eq!(
            refusal("cpu", serde_json::json!({ "a": 1, "pc": "high" })),
            "pc: expects an integer from 0 to 65535, or hexadecimal from &0000 to &FFFF, \
             written with &, #, $ or 0x before it, not \"high\""
        );
        assert_eq!(
            refusal("pins", Value::from("0x1FFFFFFFFFFFFFFFF")),
            "expects an integer from 0 to 18446744073709551615, or hexadecimal from \
             &0000000000000000 to &FFFFFFFFFFFFFFFF, written with &, #, $ or 0x before it, not \
             \"0x1FFFFFFFFFFFFFFFF\""
        );
    }

    // As a CPC's own documentation writes them, after &, and as assemblers
    // do, after #, $ or 0x.
    #[test]
    fn an_unsigned_value_is_written_in_hexadecimal_too() {
        let cpc = cpc();
        // SAFETY: as above.
        let mut copy = unsafe { std::ptr::read(cpc.machine()) };
        for (path, given, read) in [
            ("cpu.pc", "&BB06", 0xBB06),
            ("cpu.sp", "#C000", 0xC000),
            ("cpu.a", "$7f", 0x7F),
            ("cpu.hl_", "0x4000", 0x4000),
            ("crtc.registers[12]", "0X30", 0x30),
            ("cpu.b", "&5", 5),
        ] {
            copy.set(&parse(path).unwrap(), &Value::from(given))
                .unwrap();
            assert_eq!(copy.get(&parse(path).unwrap()).unwrap(), read, "{path}");
        }
    }

    #[test]
    fn a_path_is_read_as_a_c_expression_names_a_member() {
        assert_eq!(parse("").unwrap(), vec![]);
        assert_eq!(
            parse("fdc.identities[3][1]").unwrap(),
            vec![
                Segment::Field("fdc".into()),
                Segment::Field("identities".into()),
                Segment::Index(3),
                Segment::Index(1),
            ]
        );
        assert_eq!(
            parse("drives[0].cylinder").unwrap(),
            vec![
                Segment::Field("drives".into()),
                Segment::Index(0),
                Segment::Field("cylinder".into()),
            ]
        );
        for wrong in [
            ".pc",
            "cpu.",
            "cpu..pc",
            "registers[",
            "registers[x]",
            "registers]",
            "registers[0",
            "registers[-1]",
            "registers[010]",
            "registers[0x1]",
            "registers[+5]",
            "[0]",
            "a[0]b",
            "1st",
        ] {
            let problem = parse(wrong).unwrap_err();
            assert!(
                problem.starts_with(&format!("{wrong} is not a path")),
                "{problem}"
            );
        }
    }
}
